import * as React from "react"
import { cn } from "@/lib/utils"

/**
 * INK // portal — pill button.
 * Variants: primary (electric accent), danger (soft red), ghost (bordered).
 * Uses canonical shadcn vars so it renders correctly under any theme.
 */
interface PortalBtnProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: "primary" | "danger" | "ghost"
  full?: boolean
}

export function PortalBtn({
  className,
  variant = "ghost",
  full,
  children,
  disabled,
  style,
  ...props
}: PortalBtnProps) {
  const base: React.CSSProperties = {
    display: "inline-flex",
    alignItems: "center",
    justifyContent: "center",
    gap: 8,
    width: full ? "100%" : undefined,
    padding: "13px 20px",
    borderRadius: 999,
    fontWeight: 700,
    fontSize: 14,
    fontFamily: "inherit",
    cursor: disabled ? "not-allowed" : "pointer",
    opacity: disabled ? 0.45 : 1,
    transition:
      "transform .12s var(--ease, cubic-bezier(0.16,1,0.3,1)), background .15s var(--ease, cubic-bezier(0.16,1,0.3,1)), border-color .15s",
  }
  if (variant === "primary") {
    base.background = "var(--accent, #3f5c05)"
    base.color = "var(--accent-foreground, #f6f5ef)"
    base.border = "none"
  } else if (variant === "danger") {
    base.background = "var(--danger-soft, rgba(214,69,69,0.12))"
    base.color = "var(--destructive, #d64545)"
    base.border = "1px solid var(--danger-border, rgba(214,69,69,0.35))"
  } else {
    base.background = "transparent"
    base.color = "var(--foreground, #17170f)"
    base.border = "1px solid var(--ring, #c9c4b4)"
  }
  return (
    <button
      className={cn(className)}
      style={{ ...base, ...style }}
      disabled={disabled}
      onMouseDown={(e) => {
        if (disabled) return
        ;(e.currentTarget as HTMLButtonElement).style.transform = "scale(0.97)"
      }}
      onMouseUp={(e) => {
        ;(e.currentTarget as HTMLButtonElement).style.transform = "scale(1)"
      }}
      onMouseLeave={(e) => {
        ;(e.currentTarget as HTMLButtonElement).style.transform = "scale(1)"
      }}
      {...props}
    >
      {children}
    </button>
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"

/**
 * INK // portal — form field (label + child) and the matching input style.
 */
interface PortalFieldProps {
  label: string
  children: React.ReactNode
  className?: string
}

export function PortalField({ label, children, className }: PortalFieldProps) {
  return (
    <label className={cn("block", className)} style={{ marginBottom: 14 }}>
      <div
        style={{
          fontSize: 13,
          fontWeight: 700,
          marginBottom: 6,
          color: "var(--muted-foreground, #4a483d)",
        }}
      >
        {label}
      </div>
      {children}
    </label>
  )
}

export const portalInputStyle: React.CSSProperties = {
  width: "100%",
  boxSizing: "border-box",
  padding: "12px 14px",
  borderRadius: "var(--radius-sm, 10px)",
  border: "1px solid var(--ring, #c9c4b4)",
  background: "var(--muted, #efece2)",
  color: "var(--foreground, #17170f)",
  fontSize: 14,
  fontFamily: "inherit",
  outline: "none",
}

interface PortalInputProps extends React.InputHTMLAttributes<HTMLInputElement> {}

export function PortalInput({ className, style, ...props }: PortalInputProps) {
  return (
    <input
      className={cn(className)}
      style={{ ...portalInputStyle, ...style }}
      {...props}
    />
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"

/**
 * INK // portal — centered modal.
 * Backdrop blur + Escape-to-close (focus trap is left to the consumer,
 * matching the lightweight portal origin).
 */
interface PortalModalProps {
  title: string
  onClose: () => void
  children: React.ReactNode
  className?: string
}

export function PortalModal({ title, onClose, children, className }: PortalModalProps) {
  React.useEffect(() => {
    const onKey = (e: KeyboardEvent) => e.key === "Escape" && onClose()
    window.addEventListener("keydown", onKey)
    return () => window.removeEventListener("keydown", onKey)
  }, [onClose])

  return (
    <div
      className={cn("fixed inset-0 z-[900] flex items-center justify-center p-5")}
      style={{
        background: "rgba(4,5,6,0.72)",
        backdropFilter: "blur(6px)",
        WebkitBackdropFilter: "blur(6px)",
      }}
      onClick={onClose}
      role="presentation"
    >
      <div
        className={cn("w-full", className)}
        style={{
          maxWidth: 420,
          background: "var(--card, #ffffff)",
          borderRadius: "var(--radius, 14px)",
          padding: 22,
          border: "1px solid var(--ring, #c9c4b4)",
          boxShadow: "0 40px 120px rgba(0,0,0,0.6)",
        }}
        onClick={(e) => e.stopPropagation()}
        role="dialog"
        aria-modal="true"
        aria-label={title}
      >
        <div
          style={{
            fontFamily: "var(--font-display, inherit)",
            fontWeight: 800,
            fontSize: 20,
            letterSpacing: "-0.02em",
            marginBottom: 18,
            color: "var(--foreground, #17170f)",
          }}
        >
          {title}
        </div>
        {children}
      </div>
    </div>
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"

/**
 * INK // portal — full-width settings row (icon + label + value + chevron).
 * Same shape as the me.mcky.space Account settings list.
 */
interface PortalRowProps {
  icon?: React.ReactNode
  label: string
  value: string
  onClick: () => void
  className?: string
}

function ChevronRight(props: React.SVGProps<SVGSVGElement>) {
  return (
    <svg
      viewBox="0 0 16 16"
      width="14"
      height="14"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <path d="M6 3.5 10.5 8 6 12.5" />
    </svg>
  )
}

export function PortalRow({ icon, label, value, onClick, className }: PortalRowProps) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={cn(className)}
      style={{
        width: "100%",
        display: "flex",
        alignItems: "center",
        gap: 14,
        padding: "16px 4px",
        border: "none",
        borderBottom: "1px solid var(--border, #e2ded2)",
        background: "transparent",
        cursor: "pointer",
        textAlign: "left",
        fontFamily: "inherit",
        color: "var(--foreground, #17170f)",
      }}
    >
      {icon && (
        <span
          style={{
            display: "inline-flex",
            flexShrink: 0,
            color: "var(--accent, #3f5c05)",
            width: 22,
            justifyContent: "center",
          }}
        >
          {icon}
        </span>
      )}
      <span
        style={{
          fontSize: 14,
          fontWeight: 700,
          color: "var(--foreground, #17170f)",
          width: 92,
          flexShrink: 0,
        }}
      >
        {label}
      </span>
      <span
        style={{
          flex: 1,
          minWidth: 0,
          fontSize: 13,
          color: "var(--muted-foreground, #4a483d)",
          overflow: "hidden",
          textOverflow: "ellipsis",
          whiteSpace: "nowrap",
          textAlign: "right",
        }}
      >
        {value}
      </span>
      <span style={{ color: "var(--muted-text, #8a8778)", flexShrink: 0 }}>
        <ChevronRight />
      </span>
    </button>
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"

/**
 * INK // portal — section header row.
 * Accent index marker + display title + optional right-aligned hint.
 */
interface PortalSectionProps {
  index: string
  title: string
  hint?: string
  className?: string
}

export function PortalSection({ index, title, hint, className }: PortalSectionProps) {
  return (
    <div
      className={cn(className)}
      style={{
        display: "flex",
        alignItems: "baseline",
        gap: 12,
        padding: "26px 0 14px",
        borderTop: "1px solid var(--border, #e2ded2)",
      }}
    >
      <span
        style={{
          fontFamily: "var(--font-display, inherit)",
          fontWeight: 500,
          fontSize: 11,
          letterSpacing: "0.12em",
          color: "var(--accent, #3f5c05)",
          transform: "translateY(-2px)",
        }}
      >
        {index}
      </span>
      <h2
        style={{
          fontFamily: "var(--font-display, inherit)",
          fontWeight: 800,
          letterSpacing: "-0.02em",
          fontSize: 22,
          margin: 0,
          color: "var(--foreground, #17170f)",
        }}
      >
        {title}
      </h2>
      {hint && (
        <span
          style={{
            marginLeft: "auto",
            fontSize: 12,
            color: "var(--muted-text, #8a8778)",
            fontWeight: 600,
          }}
        >
          {hint}
        </span>
      )}
    </div>
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"

/**
 * INK // portal — transient toast + the hook that drives it.
 * kind "ok" → --success, kind "err" → --destructive.
 */
export interface PortalToastState {
  text: string
  kind: "ok" | "err"
}

export function usePortalToast(ms = 3200) {
  const [toast, setToast] = React.useState<PortalToastState | null>(null)
  const timer = React.useRef<ReturnType<typeof setTimeout> | undefined>(undefined)
  const show = (text: string, kind: PortalToastState["kind"] = "ok") => {
    clearTimeout(timer.current)
    setToast({ text, kind })
    timer.current = setTimeout(() => setToast(null), ms)
  }
  React.useEffect(() => () => clearTimeout(timer.current), [])
  return { toast, show }
}

export function PortalToast({
  toast,
  className,
}: {
  toast: PortalToastState | null
  className?: string
}) {
  if (!toast) return null
  const ok = toast.kind === "ok"
  return (
    <div
      role="status"
      className={cn(className)}
      style={{
        position: "fixed",
        bottom: 24,
        left: "50%",
        transform: "translateX(-50%)",
        zIndex: 1000,
        background: ok ? "var(--success, #1f9d5c)" : "var(--destructive, #d64545)",
        color: ok ? "#0b0e08" : "#fff",
        fontWeight: 700,
        fontSize: 14,
        padding: "12px 20px",
        borderRadius: 999,
        boxShadow: "0 12px 40px rgba(0,0,0,0.5)",
        maxWidth: "90vw",
        textAlign: "center",
      }}
    >
      {toast.text}
    </div>
  )
}
